starter.template:
// Switches to LEDs, one XOR gate and an active-low key.
// Port names from Terasic's System Builder .qsf, which gives each bit its FPGA pin.
module top (
  input  [9:0] SW,      // 10 slide switches, up = 1
  input  [1:0] KEY,     // 2 push buttons, 0 while pressed
  output [9:0] LEDR
);
  assign LEDR[7:0] = SW[7:0];          // SW7-SW0 straight to the LEDs above them
  assign LEDR[8]   = SW[8] ^ SW[9];    // lit when exactly one of SW8 and SW9 is up
  assign LEDR[9]   = ~KEY[0];          // a key reads 0 when pressed, so invert it
endmodule

